// A sweep over the language and the library, one line of output per area, against .NET: generic math, patterns,
// iterators, async, formatting, dates, numbers, text, regular expressions, enums, spans, LINQ, collections, threads.
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Numerics;
using System.Runtime.InteropServices;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;

interface IShape { double Area(); string Name => GetType().Name; }
interface IAddable<T> where T : IAddable<T> { static abstract T operator +(T a, T b); static abstract T Zero { get; } }
readonly record struct V2(double X, double Y) : IAddable<V2>
{
    public static V2 operator +(V2 a, V2 b) => new(a.X + b.X, a.Y + b.Y);
    public static V2 Zero => default;
}
record Circle(double R) : IShape { public double Area() => Math.PI * R * R; }
record Rect(double W, double H) : IShape { public double Area() => W * H; public void Deconstruct(out double w, out double h, out double a) { w = W; h = H; a = Area(); } }
[Flags] enum Perm { None = 0, Read = 1, Write = 2, Exec = 4, All = 7 }
enum Color : byte { Red = 1, Green, Blue = 10 }
ref struct Walker { Span<int> _s; int _i; public Walker(Span<int> s) { _s = s; _i = 0; } public bool Next(out int v) { if (_i < _s.Length) { v = _s[_i++]; return true; } v = 0; return false; } }
abstract class Animal { public abstract string Sound(); public virtual string Describe() => $"{GetType().Name} says {Sound()}"; }
class Dog : Animal { public override string Sound() => "woof"; }
class Puppy : Dog { public override string Sound() => "yip"; public override string Describe() => base.Describe() + "!"; }
class Matrix
{
    readonly double[,] _m; public Matrix(int n) { _m = new double[n, n]; }
    public double this[int r, int c] { get => _m[r, c]; set => _m[r, c] = value; }
    public static Matrix operator *(Matrix a, Matrix b) { int n = a._m.GetLength(0); var r = new Matrix(n); for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) { double s = 0; for (int k = 0; k < n; k++) s += a[i, k] * b[k, j]; r[i, j] = s; } return r; }
}

static class Program
{
    static void T(string name, Action a)
    {
        try { a(); } catch (Exception e) { Console.WriteLine(name + " threw " + e.GetType().Name + ": " + e.Message); }
    }
    static T Sum<T>(IEnumerable<T> xs) where T : IAddable<T> { var s = T.Zero; foreach (var x in xs) s += x; return s; }
    static TNum SumN<TNum>(params TNum[] xs) where TNum : INumber<TNum> { var s = TNum.Zero; foreach (var x in xs) s += x; return s; }
    static string Classify(object? o) => o switch
    {
        null => "null",
        int i and > 100 => "big int " + i,
        int i => "int " + i,
        string { Length: 0 } => "empty string",
        string s when s.StartsWith('a') => "a-string " + s,
        string s => "string " + s,
        Circle { R: > 5 } c => "big circle " + c.R,
        Rect(var w, var h, var a) => $"rect {w}x{h}={a}",
        IShape sh => "shape " + sh.Name,
        int[] { Length: > 2 } arr => "array starting " + arr[0],
        (int a, string b) => "tuple " + a + b,
        _ => "other " + o.GetType().Name,
    };
    static IEnumerable<int> Fib() { int a = 0, b = 1; while (true) { yield return a; (a, b) = (b, a + b); } }
    static async Task<int> AddAsync(int a, int b) { await Task.Yield(); return a + b; }
    static async Task<string> ChainAsync() { int x = await AddAsync(1, 2); await Task.Delay(1); int y = await AddAsync(x, 10); try { await FailAsync(); } catch (InvalidOperationException e) { return "caught " + e.Message + " " + y; } return "no"; }
    static async Task FailAsync() { await Task.Yield(); throw new InvalidOperationException("boom"); }
    static async IAsyncEnumerable<int> CountAsync(int n) { for (int i = 0; i < n; i++) { await Task.Yield(); yield return i * i; } }

    [UnmanagedCallersOnly(EntryPoint = "main")]
    static void Main()
    {
        CultureInfo.CurrentCulture = CultureInfo.InvariantCulture;
        T("generic math", () => { Console.WriteLine(Sum(new[] { new V2(1, 2), new V2(3, 4) })); Console.WriteLine(SumN(1, 2, 3) + " " + SumN(1.5, 2.5) + " " + SumN(1.1m, 2.2m) + " " + SumN<BigInteger>(BigInteger.Pow(2, 100), 1)); });
        T("patterns", () => { foreach (var o in new object?[] { null, 5, 500, "", "abc", "xyz", new Circle(9), new Circle(1), new Rect(2, 3), new[] { 7, 8, 9 }, (1, "z"), 2.5 }) Console.WriteLine(Classify(o)); });
        T("virtual", () => { foreach (Animal a in new Animal[] { new Dog(), new Puppy() }) Console.WriteLine(a.Describe()); });
        T("iter", () => Console.WriteLine(string.Join(",", Fib().Skip(5).Take(10)) + " " + Fib().TakeWhile(x => x < 1000).Where(x => x % 2 == 0).Sum()));
        T("async", () => { Console.WriteLine(ChainAsync().GetAwaiter().GetResult()); var t = Task.WhenAll(Enumerable.Range(0, 5).Select(i => AddAsync(i, i))); Console.WriteLine(string.Join(",", t.Result)); async Task<int> Loop() { int s = 0; await foreach (var v in CountAsync(5)) s += v; return s; } Console.WriteLine(Loop().Result); var vt = new ValueTask<int>(7); Console.WriteLine(vt.Result); });
        T("task run", () => { var r = Task.Run(() => Enumerable.Range(1, 100).Sum()).Result; var tcs = new TaskCompletionSource<string>(); new Thread(() => tcs.SetResult("from thread")).Start(); Console.WriteLine(r + " " + tcs.Task.Result); var cts = new CancellationTokenSource(); cts.Cancel(); try { Task.Delay(1000, cts.Token).Wait(); } catch (AggregateException e) { Console.WriteLine(e.InnerException!.GetType().Name); } });
        T("format", () => { double d = 1234567.891; Console.WriteLine($"{d:N2} {d:F1} {d:E3} {d:G5} {0.256:P1} {255:X4} {255:D6} {-5,6}|{"ab",-5}| {12.5m:C} {d:#,##0.00;(#)} {1e-7} {float.MaxValue} {double.NaN} {1.0 / 3} {100000000000000000000.0} {0.1f + 0.2f} {(decimal)1 / 3}"); Console.WriteLine(string.Format("{0:000.00} {1:yyyy-MM-dd HH:mm:ss} {2:hh\\:mm} {3:o}", 3.14159, new DateTime(2024, 2, 29, 13, 5, 9), TimeSpan.FromMinutes(135), new DateTime(2020, 1, 2, 3, 4, 5, DateTimeKind.Utc))); });
        T("dates", () => { var dt = new DateTime(2024, 2, 29).AddYears(1).AddMonths(13).AddDays(-400.5); Console.WriteLine(dt.ToString("R") + " " + dt.DayOfWeek + " " + dt.DayOfYear + " " + (dt - new DateTime(2000, 1, 1)).TotalHours + " " + DateTime.Parse("2021-03-04T05:06:07", CultureInfo.InvariantCulture).Ticks + " " + DateTimeOffset.FromUnixTimeSeconds(1700000000).ToString("u") + " " + TimeSpan.Parse("1.02:03:04.5") + " " + new DateOnly(2024, 12, 31).AddDays(1) + " " + new TimeOnly(23, 59).AddMinutes(2) + " " + DateTime.DaysInMonth(2100, 2) + " " + ISOWeek.GetWeekOfYear(new DateTime(2021, 1, 3))); });
        T("numbers", () => { Console.WriteLine(BigInteger.Parse("123456789012345678901234567890") * 987654321 % 1000000007 + " " + BigInteger.ModPow(3, 200, 1000000007) + " " + decimal.Round(2.345m, 2, MidpointRounding.AwayFromZero) + " " + Math.Round(2.5) + " " + Math.Round(-2.5, MidpointRounding.AwayFromZero) + " " + (int)3.99 + " " + unchecked((int)3e10) + " " + (long)double.Parse("1e30") + " " + Math.IEEERemainder(10, 3) + " " + 7 / -2 + " " + 7 % -2 + " " + Math.FusedMultiplyAdd(2, 3, 4) + " " + Complex.Sqrt(-4) + " " + Half.MaxValue + " " + Int128.MaxValue + " " + UInt128.Parse("340282366920938463463374607431768211455") + " " + BitConverter.DoubleToInt64Bits(-0.0) + " " + double.Parse("1e308") * 10 + " " + int.Parse("-12,345", NumberStyles.AllowThousands | NumberStyles.AllowLeadingSign) + " " + Convert.ToString(-10, 2) + " " + Convert.ToInt32("7f", 16) + " " + 1.5.CompareTo(double.NaN)); try { checked { int x = int.MaxValue; x++; } } catch (OverflowException) { Console.WriteLine("overflow"); } });
        T("math", () => Console.WriteLine(string.Join(" ", new[] { Math.Sin(1), Math.Cos(1), Math.Tan(1), Math.Atan2(1, 2), Math.Exp(1.5), Math.Log(10), Math.Log10(1000), Math.Log2(10), Math.Pow(2, 0.5), Math.Sqrt(2), Math.Cbrt(27), Math.Sinh(1), Math.Asin(0.5), Math.Floor(-1.5), Math.Ceiling(-1.5), Math.Truncate(-1.7), Math.Abs(-0.0), Math.BitIncrement(1), Math.ScaleB(1, 10), double.Hypot(3, 4) }.Select(x => x.ToString("R")))));
        T("strings", () => { var s = "The quick brown fox, jumps over the lazy dog — naïve café Ünïcödé 𝄞"; Console.WriteLine(s.ToUpperInvariant() + "|" + s.Length + "|" + s.IndexOf("fox", StringComparison.Ordinal) + "|" + s.Replace("quick", "slow").Substring(4, 10) + "|" + string.Join("/", s.Split(new[] { ' ', ',' }, StringSplitOptions.RemoveEmptyEntries).Select(w => w.Length)) + "|" + s.PadLeft(70, '*').TrimStart('*').Length + "|" + string.Compare("apple", "Banana", StringComparison.OrdinalIgnoreCase) + "|" + "abc".CompareTo("abd") + "|" + s.Contains("LAZY", StringComparison.OrdinalIgnoreCase) + "|" + new string(s.Reverse().Skip(2).Take(5).ToArray()) + "|" + s.Normalize(NormalizationForm.FormD).Length + "|" + Encoding.UTF8.GetByteCount(s) + "|" + Convert.ToBase64String(Encoding.UTF8.GetBytes("héllo")) + "|" + Encoding.UTF8.GetString(Convert.FromBase64String("aMOpbGxv")) + "|" + string.Concat(Encoding.Unicode.GetBytes("hi").Select(b => b.ToString("x2"))) + "|" + "a,b;c".Split(',', ';').Length + "|" + string.IsNullOrWhiteSpace(" \t") + "|" + "x".Equals("X", StringComparison.InvariantCultureIgnoreCase) + "|" + "ß".ToUpperInvariant() + "|" + char.IsLetter('é') + char.GetUnicodeCategory("𝄞", 0) + "|" + new Rune(0x1F600).Utf16SequenceLength + "|" + "Hello"[^2..] + "Hello"[1..^1] + "|" + string.Create(5, 'x', (sp, c) => sp.Fill(c)) + "|" + "tEST".AsSpan().ToString() + "|" + $"{"a"}{1}{null}{2.5}{'c'}{true}"); var sb = new StringBuilder(); sb.Append("x", 0, 1).AppendFormat("{0:D3}", 7).Append('\n').Insert(0, "<<").Replace("x", "yy").Append(1.5).Append('c', 3).Remove(2, 1); sb.Length -= 1; Console.WriteLine(sb.ToString().Replace("\r", "").Replace("\n", "\\n") + sb.Length); });
        T("regex", () => { var m = Regex.Match("John Smith <john.smith@example.com>, age 42", @"(?<first>\w+)\s+(?<last>\w+)\s+<(?<mail>[^>]+)>.*?(\d+)"); Console.WriteLine(m.Groups["first"].Value + "|" + m.Groups["mail"].Value + "|" + m.Groups[1].Value + "|" + Regex.Replace("a1b22c333", @"\d+", x => (x.Value.Length * 2).ToString()) + "|" + string.Join(",", Regex.Split("a, b;c  d", @"[,;\s]+")) + "|" + Regex.IsMatch("2024-02-29", @"^\d{4}-\d{2}-\d{2}$") + "|" + Regex.Matches("aXbXXc", "X+", RegexOptions.IgnoreCase).Count + "|" + new Regex(@"(a+)(b*)\1", RegexOptions.Compiled).Match("xaabbaay").Value + "|" + Regex.Escape("a.b*c")); });
        T("enums", () => { var p = Perm.Read | Perm.Exec; Console.WriteLine(p + " " + p.HasFlag(Perm.Exec) + " " + (Perm)7 + " " + (Perm)8 + " " + Enum.Parse<Perm>("Write, Read") + " " + Enum.TryParse<Color>("green", true, out var c) + c + " " + (int)Color.Blue + " " + string.Join(",", Enum.GetNames<Color>()) + " " + string.Join(",", Enum.GetValues<Color>().Cast<byte>()) + " " + Enum.IsDefined(typeof(Color), (byte)3) + " " + Color.Red.ToString("D") + " " + p.ToString("X") + " " + Enum.GetUnderlyingType(typeof(Color)).Name + " " + ((Color)99).ToString() + " " + Color.Green.CompareTo(Color.Blue)); });
        T("spans", () => { Span<int> st = stackalloc int[8]; for (int i = 0; i < 8; i++) st[i] = i * i; var w = new Walker(st[2..6]); int sum = 0; while (w.Next(out int v)) sum += v; st.Reverse(); Console.WriteLine(sum + " " + st[0] + " " + st.IndexOf(9) + " " + st.BinarySearch(100) + " " + MemoryMarshal.Cast<int, byte>(st).Length + " " + "a b c".AsSpan().Count(' ') + " " + st.ToArray().AsMemory(1, 3).Span[1] + " " + "hello world".AsSpan(6).SequenceEqual("world") + " " + int.Parse("  42 ".AsSpan().Trim()) + " " + BitConverter.ToString(BitConverter.GetBytes(0x12345678)) + " " + System.Buffers.Binary.BinaryPrimitives.ReadInt32BigEndian(new byte[] { 1, 2, 3, 4 })); Span<char> buf = stackalloc char[32]; 123.456.TryFormat(buf, out int n, "F1"); Console.WriteLine(buf[..n].ToString() + " " + (ReadOnlySpan<byte>)"utf8"u8.ToArray() switch { [117, .., 56] => "u..8", _ => "?" }); });
        T("matrix", () => { var a = new Matrix(3); var b = new Matrix(3); for (int i = 0; i < 3; i++) for (int j = 0; j < 3; j++) { a[i, j] = i + j; b[i, j] = i * j + 1; } var c = a * b; Console.WriteLine(c[0, 0] + " " + c[1, 2] + " " + c[2, 2]); });
        T("linq", () => { var people = new[] { ("Ann", 31, "NL"), ("Bob", 25, "US"), ("Cy", 31, "US"), ("Di", 44, "NL"), ("Ed", 25, "FR") }; var q = from p in people group p by p.Item3 into g orderby g.Key select $"{g.Key}:{g.Count()}:{g.Average(x => x.Item2):F1}:{string.Join("+", g.Select(x => x.Item1))}"; Console.WriteLine(string.Join(" ", q)); var j = from p in people join c in new[] { ("NL", "Netherlands"), ("US", "States") } on p.Item3 equals c.Item1 into cs from c in cs.DefaultIfEmpty() select p.Item1 + "@" + (c.Item2 ?? "?"); Console.WriteLine(string.Join(",", j)); Console.WriteLine(people.OrderByDescending(p => p.Item2).ThenBy(p => p.Item1).Select(p => p.Item1).Aggregate((x, y) => x + y) + " " + people.MaxBy(p => p.Item2).Item1 + " " + people.ToLookup(p => p.Item2)[25].Count() + " " + Enumerable.Range(1, 10).Chunk(3).Select(c => c.Sum()).Last() + " " + new[] { 1, 2, 3 }.SelectMany(x => Enumerable.Repeat(x, x)).Count() + " " + new[] { 3, 1, 2 }.Order().SequenceEqual(new[] { 1, 2, 3 }) + " " + new[] { 1, 2, 2, 3 }.Except(new[] { 2 }).Union(new[] { 9 }).Intersect(new[] { 1, 9, 3 }).Count() + " " + Enumerable.Range(0, 20).Where((x, i) => i % 3 == 0).Any(x => x == 9) + " " + new[] { "b", "a" }.DistinctBy(s => s.Length).Single() + " " + Enumerable.Empty<int>().DefaultIfEmpty(-1).First() + " " + new[] { 1.5, 2.5 }.Average() + " " + new int?[] { 1, null, 3 }.Sum() + " " + new[] { 1, 2, 3, 4 }.Zip(new[] { "a", "b" }, (n, s) => s + n).Last() + " " + people.GroupBy(p => p.Item2).Where(g => g.Count() > 1).Count() + " " + new[] { 5, 3, 8 }.Index().MaxBy(t => t.Item).Index + " " + people.CountBy(p => p.Item3).First().Value + " " + Enumerable.Range(0, 5).Reverse().ElementAt(^1)); });
        T("collections", () => { var sd = new SortedDictionary<string, int>(StringComparer.OrdinalIgnoreCase) { ["b"] = 1, ["A"] = 2, ["c"] = 3 }; var ll = new LinkedList<int>(new[] { 1, 2, 3 }); ll.AddAfter(ll.First!, 9); var ss = new SortedSet<int> { 5, 1, 3 }; var bits = new System.Collections.BitArray(10); bits[3] = true; var st = new Stack<int>(new[] { 1, 2, 3 }); var pq = new PriorityQueue<string, int>(); pq.Enqueue("lo", 5); pq.Enqueue("hi", 1); var dict = new Dictionary<(int, string), List<int>>(); dict[(1, "a")] = new() { 1 }; dict.TryAdd((1, "a"), new()); var ro = new System.Collections.ObjectModel.ReadOnlyCollection<int>(new[] { 1, 2 }); var imm = System.Collections.Immutable.ImmutableList.Create(1, 2).Add(3); var cd = new System.Collections.Concurrent.ConcurrentDictionary<int, int>(); cd.AddOrUpdate(1, 1, (k, v) => v + 1); cd.AddOrUpdate(1, 1, (k, v) => v + 1); Console.WriteLine(string.Join(",", sd.Keys) + " " + string.Join(",", ll) + " " + ss.Min + ss.GetViewBetween(2, 4).Count + " " + bits.Cast<bool>().Count(b => b) + " " + st.Peek() + " " + pq.Dequeue() + " " + dict.Count + " " + ro.Count + " " + imm.Count + " " + cd[1] + " " + new HashSet<int> { 1, 2, 3 }.IsSupersetOf(new[] { 1, 3 }) + " " + new List<int> { 3, 1, 2 }.BinarySearch(2) + " " + new Queue<int>(new[] { 1, 2 }).Contains(2)); });
        T("threads", () => { int counter = 0; object gate = new(); var ts = Enumerable.Range(0, 4).Select(i => new Thread(() => { for (int k = 0; k < 1000; k++) lock (gate) counter++; })).ToList(); ts.ForEach(t => t.Start()); ts.ForEach(t => t.Join()); long total = 0; Parallel.For(0, 100, i => Interlocked.Add(ref total, i)); var tl = new ThreadLocal<int>(() => 5); using var sem = new SemaphoreSlim(1); sem.Wait(); sem.Release(); using var mre = new ManualResetEventSlim(); ThreadPool.QueueUserWorkItem(_ => mre.Set()); Console.WriteLine(counter + " " + total + " " + tl.Value + " " + mre.Wait(5000) + " " + Volatile.Read(ref counter) + " " + new[] { 1, 2, 3, 4 }.AsParallel().Sum()); });
        T("misc", () => { var g = Guid.Parse("12345678-1234-1234-1234-1234567890ab"); var u = new Uri("https://example.com:8080/a/b?x=1#f"); var ver = new Version(1, 2, 3); var rnd = new Random(42); var lz = new Lazy<int>(() => 9); var wr = new WeakReference(new object()); Nullable<int> ni = null; var tup = Tuple.Create(1, "a"); var (q, r) = Math.DivRem(17, 5); Console.WriteLine(g.ToString("N") + " " + u.Host + u.Port + u.AbsolutePath + u.Query + " " + (ver > new Version(1, 2)) + " " + rnd.Next(100) + " " + rnd.NextDouble().ToString("F4") + " " + lz.Value + " " + ni.GetValueOrDefault(3) + " " + (ni ?? 4) + " " + tup + " " + q + r + " " + HashCode.Combine(1, 2).GetType().Name + " " + typeof(Dictionary<string, List<int>>).Name + " " + typeof(int[]).FullName + " " + nameof(Program.Main) + " " + default(DateTime).Year + " " + sizeof(decimal) + " " + " " + ((object)1 is int) + " " + Convert.ChangeType("42", typeof(long)) + " " + string.Join(",", typeof(Perm).GetEnumNames()) + " " + new Circle(2).Equals(new Circle(2)) + " " + new Circle(2) + " " + (new Rect(1, 2) with { H = 5 }).Area() + " " + Activator.CreateInstance<List<int>>().Count + " " + typeof(Circle).GetProperty("R")!.GetValue(new Circle(3))); });
        T("exceptions", () => { int Depth(int n) => n == 0 ? throw new ArgumentException("deep", "n") : Depth(n - 1); try { try { Depth(3); } finally { Console.Write("finally "); } } catch (ArgumentException e) when (e.ParamName == "n") { Console.Write(e.Message + " "); } try { object o = "s"; var i = (int)o; } catch (InvalidCastException) { Console.Write("cast "); } try { var a = new int[2]; a[2] = 1; } catch (IndexOutOfRangeException) { Console.Write("index "); } try { string? s = null; _ = s!.Length; } catch (NullReferenceException) { Console.Write("null "); } try { _ = 1 / int.Parse("0"); } catch (DivideByZeroException) { Console.Write("div "); } try { new Dictionary<int, int>()[1].ToString(); } catch (KeyNotFoundException) { Console.Write("key "); } try { throw new AggregateException(new Exception("a"), new FormatException("b")); } catch (AggregateException e) { Console.Write(e.InnerExceptions.Count + " "); } try { int.Parse("x"); } catch (FormatException e) { Console.Write(e.Message + " "); } try { Enumerable.Empty<int>().First(); } catch (InvalidOperationException e) { Console.Write(e.Message + " "); } try { "abc".Substring(5); } catch (ArgumentOutOfRangeException e) { Console.Write(e.ParamName + " "); } try { ((IDisposable)null!).Dispose(); } catch (NullReferenceException) { Console.WriteLine("done"); } });
    }
}
